type record MyMessageType 
  {
     charstring field1,
     bitstring field2,
     record of integer field3,
     map from charstring to charstring field4
  }
  template MyMessageType mw_myTemplate:= 
  {
     field1 := "abcxyz*", // "*" is not a matching symbol, it matches the "*" character
     field2 := '10*11'B,  // where "*" may be any sequence of bits (possibly empty) 
     field3 := {*, 2, 3}  // where "*"may be any number of integer values or omitted 
     field4 := { *, ["host"] := "localhost", ["port"] := ? }
  }
  type charstring MyStrings[4];
  function f() runs on MyComponent {
     myPCO.receive(MyStrings:{"abyz", *, "abc" });
  }

